challenge.starter:
const planet = "Mars";
let info = "";

// switch ile info'ya değer ver

console.log(planet, "→", info);

challenge.solution:
const planet = "Mars";
let info = "";

// switch ile info'ya değer ver
switch (planet) {
  case "Merkür":
    info = "En yakın gezegen";
    break;
  case "Mars":
    info = "Kızıl gezegen";
    break;
  case "Jüpiter":
    info = "En büyük gezegen";
    break;
  default:
    info = "Bilinmeyen gezegen";
}

console.log(planet, "→", info);

project_task.starter:
let lives = 1;
let stars = 8;
let message = "";

// if / else if / else ile message'a değer ver

console.log(message);

project_task.solution:
let lives = 1;
let stars = 8;
let message = "";

// if / else if / else ile message'a değer ver
if (lives === 0) {
  message = "Oyun bitti!";
} else if (stars >= 10) {
  message = "Tebrikler, kazandın!";
} else {
  message = `Devam! ${10 - stars} yıldız kaldı.`;
}

console.log(message);

check.js:
assert(message === "Devam! 2 yıldız kaldı.", "Can 1, yıldız 8 iken message 'Devam! 2 yıldız kaldı.' olmalı.");
assert(_code.includes("Oyun bitti!") && _code.includes("Tebrikler, kazandın!"), "Diğer iki durumun mesajları da kodda olmalı.");
assert(!_code.includes("2 yıldız kaldı"), "Kalan yıldız sayısını elle yazma; 10 - stars ile hesapla.");

