project_task.solution:
const dailyGoal = 3;
let tasksDone = 1;
let message = "";

// message'a değer ver
if (tasksDone >= dailyGoal) {
  message = "Bugünün hedefi tamam!";
} else if (tasksDone === 0) {
  message = "Hadi başlayalım!";
} else {
  message = `${dailyGoal - tasksDone} görev kaldı`;
}

console.log(message);

check.js:
assert(message === "2 görev kaldı", "1 görev yapılmışken message '2 görev kaldı' olmalı.");
assert(_code.includes("Bugünün hedefi tamam!") && _code.includes("Hadi başlayalım!"), "Diğer iki mesaj da kodda olmalı.");
assert(!/["'`]2 görev/.test(_code), "Kalan görev sayısını elle yazma; hesapla.");

project_task.starter:
const correct = "Pasifik";
const answer = "Pasifik";
let score = 40;

// Cevabı değerlendir

console.log("Puan:", score);

project_task.solution:
const correct = "Pasifik";
const answer = "Pasifik";
let score = 40;

// Cevabı değerlendir
if (answer === correct) {
  score += 10;
  console.log("Doğru! +10 puan");
} else {
  console.log(`Yanlış. Doğru cevap: ${correct}`);
}

console.log("Puan:", score);

check.js:
assert(score === 50, "Doğru cevaptan sonra score 50 olmalı.");
assert(_lines[0] === "Doğru! +10 puan" && _lines.includes("Puan: 50"), "Çıktı 'Doğru! +10 puan' ve 'Puan: 50' olmalı.");
assert(_code.includes("Yanlış. Doğru cevap:"), "Yanlış cevap durumu da kodda olmalı.");
